public final class VisionChecks {
 interface Handler{void handle(HttpExchange e)throws IOException;}
 static final class Headers extends HashMap<String,String>{String getFirst(String key){return get(key.toLowerCase(Locale.ROOT));}void set(String key,String value){put(key.toLowerCase(Locale.ROOT),value);}}
 static final class HttpExchange {
  final Socket socket;final Headers input=new Headers(),output=new Headers();final byte[] body;
  HttpExchange(Socket s,Headers h,byte[] b){socket=s;input.putAll(h);body=b;}
  Headers getRequestHeaders(){return input;}Headers getResponseHeaders(){return output;}InputStream getRequestBody(){return new ByteArrayInputStream(body);}OutputStream getResponseBody()throws IOException{return socket.getOutputStream();}
  void sendResponseHeaders(int code,long length)throws IOException{StringBuilder headers=new StringBuilder("HTTP/1.1 "+code+" Test\r\nContent-Length: "+length+"\r\nConnection: close\r\n");for(Map.Entry<String,String> e:output.entrySet())headers.append(e.getKey()).append(": ").append(e.getValue()).append("\r\n");socket.getOutputStream().write(headers.append("\r\n").toString().getBytes(StandardCharsets.US_ASCII));}
 }
 static final class HttpServer {
  final ServerSocket socket;final Map<String,Handler> handlers=new HashMap<>();volatile boolean running=true;
  HttpServer(InetSocketAddress address)throws IOException{socket=new ServerSocket();socket.bind(address);}
  static HttpServer create(InetSocketAddress address,int backlog)throws IOException{return new HttpServer(address);}void createContext(String path,Handler handler){handlers.put(path,handler);}InetSocketAddress getAddress(){return (InetSocketAddress)socket.getLocalSocketAddress();}
  void start(){Thread t=new Thread(()->{while(running)try(Socket s=socket.accept()){s.setSoTimeout(5000);InputStream in=s.getInputStream();ByteArrayOutputStream head=new ByteArrayOutputStream();int c;while((c=in.read())!=-1){head.write(c);byte[] b=head.toByteArray();int n=b.length;if(n>=4&&b[n-4]==13&&b[n-3]==10&&b[n-2]==13&&b[n-1]==10)break;if(n>32768)throw new IOException("Headers too large");}String[] lines=new String(head.toByteArray(),StandardCharsets.US_ASCII).split("\r\n");Headers h=new Headers();for(int i=1;i<lines.length;i++){int split=lines[i].indexOf(':');if(split>0)h.set(lines[i].substring(0,split),lines[i].substring(split+1).trim());}int length=Integer.parseInt(h.getFirst("content-length"));byte[] body=new byte[length];for(int at=0;at<length;){int n=in.read(body,at,length-at);if(n<0)throw new EOFException();at+=n;}Handler handler=handlers.get(lines[0].split(" ")[1]);if(handler==null)throw new IOException("Missing context");handler.handle(new HttpExchange(s,h,body));}catch(IOException e){if(running)throw new RuntimeException(e);}},"test-http");t.setDaemon(true);t.start();}
  void stop(int delay){running=false;try{socket.close();}catch(IOException ignored){}}
 }
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}interface Action{void run()throws Exception;}static void reject(Action a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}check(failed,why);}
 static final String SCENE="{\"overview\":\"Podría ser una escena de prueba\",\"regions\":[{\"box\":[0.1,0.2,0.6,0.8],\"label\":\"Podría ser una hoja\",\"analogy\":\"recuerda a una almendra\"}]}";
 static void respond(HttpExchange e,int status,String text)throws IOException{byte[] data=text.getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(status,data.length);try(OutputStream out=e.getResponseBody()){out.write(data);}}
 static String request(HttpExchange e)throws IOException{try(InputStream in=e.getRequestBody();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
 public static void main(String[] args)throws Exception{
  String value=Json.write(Json.object("texto","ñ\n\"\\", "lista",Arrays.asList(1,true,null)));Map<?,?> decoded=(Map<?,?>)Json.parse(value);check(decoded.get("texto").equals("ñ\n\"\\"),"JSON Unicode and escaping");for(String bad:new String[]{"{\"a\":1,\"a\":2}","NaN","[1,]","{\"box\":Infinity}","[01]","{} trailing"})reject(()->Json.parse(bad),"malformed JSON rejected");
  ImageScene s=ImageScene.fromJson(SCENE,"Hipótesis de prueba");check(s.regions.size()==1&&s.regions.get(0).analogy.contains("almendra"),"separate identity and analogy");check(!s.regions.get(0).description(false).contains("hoja"),"hidden interpretations omitted from speech");check(s.regions.get(0).description(true).contains("Hipótesis"),"source attached to each hypothesis");reject(()->ImageScene.fromJson(SCENE.replace("0.6","1.6"),"test"),"out of image boxes rejected");reject(()->ImageScene.fromJson(SCENE.replace("0.6","0.1"),"test"),"zero width rejected");
  Geometry source=new Geometry(4,Arrays.asList(new Geometry.Shape(Curriculum.points(100,100,500,100,500,350,100,350),true,false),new Geometry.Shape(Curriculum.points(250,180,350,180,350,280,250,280),true,false,3,true)));
  Geometry focused=ImageScene.focus(source,new ImageScene.Region(0,0,1,1,"","",""),0,0,600,450);check(focused.shapes.size()==2&&focused.shapes.get(1).hole,"focus preserves interior holes");check(source.shapes.get(0).points.get(0).x==100,"source geometry not moved");
  Geometry line=new Geometry(0,Arrays.asList(new Geometry.Shape(Curriculum.points(0,225,200,225,300,225,600,225),false,true)));Geometry clipped=ImageScene.focus(line,new ImageScene.Region(.25,.1,.75,.9,"","",""),0,0,600,450);check(clipped.shapes.size()==1&&!clipped.shapes.get(0).closed,"clipping joins real continuity without inventing closure");for(Geometry.Shape shape:clipped.shapes)for(Geometry.Point p:shape.points)check(p.x>=0&&p.x<=600&&p.y>=0&&p.y<=450,"zoom coordinates in frame");
  ImageScene unknown=new ImageScene();unknown.addUnknown(source,0,0,600,450);check(unknown.regions.size()==1&&unknown.regions.get(0).label.contains("sin identificar"),"unknown shapes retained, holes not separate objects");ImageScene empty=new ImageScene();empty.addUnknown(new Geometry(0,new ArrayList<Geometry.Shape>()),0,0,600,450);check(empty.regions.size()==1,"empty extraction keeps whole image explorable");
  HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);final int[] requests={0};final String[] headers={"",""},payload={"",""};
  server.createContext("/chat",e->{requests[0]++;headers[0]=e.getRequestHeaders().getFirst("Authorization");payload[0]=request(e);respond(e,200,Json.write(Json.object("choices",Arrays.asList(Json.object("message",Json.object("content",SCENE))))));});
  server.createContext("/gemini/models/test:generateContent",e->{requests[0]++;headers[1]=e.getRequestHeaders().getFirst("x-goog-api-key");payload[1]=request(e);respond(e,200,Json.write(Json.object("candidates",Arrays.asList(Json.object("content",Json.object("parts",Arrays.asList(Json.object("text",SCENE))))))));});
  server.createContext("/bad",e->respond(e,200,"{}"));server.createContext("/redirect",e->{e.getResponseHeaders().set("Location","/chat");respond(e,302,"");});server.createContext("/error",e->respond(e,401,"secret response should not leak"));server.start();
  try{String base="http://127.0.0.1:"+server.getAddress().getPort();ImageScene chat=VisionApi.analyze(new byte[]{1,2,3},"compatible",base+"/chat","test","test-only-key");ImageScene gemini=VisionApi.analyze(new byte[]{1,2,3},"gemini",base+"/gemini","test","test-only-key");check(chat.regions.size()==1&&gemini.regions.size()==1,"both API protocols parse structured scenes");check(headers[0].equals("Bearer test-only-key")&&headers[1].equals("test-only-key"),"provider-specific auth headers");check(payload[0].contains("data:image/png;base64,AQID")&&payload[1].contains("inline_data"),"image attached using each provider format");check(!payload[0].contains("test-only-key")&&!payload[1].contains("test-only-key"),"keys absent from request JSON");reject(()->VisionApi.analyze(new byte[0],"compatible",base+"/bad","test",""),"malformed response rejected");int before=requests[0];reject(()->VisionApi.analyze(new byte[0],"compatible",base+"/redirect","test",""),"redirect rejected");check(requests[0]==before,"credentials never follow redirect");reject(()->VisionApi.analyze(new byte[0],"compatible","http://example.com/chat","test",""),"remote cleartext rejected before sending");reject(()->VisionApi.analyze(new byte[0],"gemini",base+"/gemini","../wrong",""),"invalid Gemini model path rejected");try{VisionApi.analyze(new byte[0],"compatible",base+"/error","test","");throw new AssertionError("HTTP error accepted");}catch(IOException error){check(!error.getMessage().contains("secret response"),"HTTP response body not exposed in errors");}
  }finally{server.stop(0);}System.out.println("PASS "+checks+" semantic regions, zoom and API protocol checks (local mock services; no paid API calls).");
 }
}
